/**
 * inactive has no purchase; pending is a first purchase whose order has not been accepted;
 * provisioning is a first purchase being activated; active permits creation within available
 * capacity; suspended refuses new creation; failed means the first purchase failed, as
 * failure_reason states. A pending change keeps the current status and limit until it is applied.
 */
export type SnapshotQuotaStatus = (typeof SnapshotQuotaStatus)[keyof typeof SnapshotQuotaStatus];

export const SnapshotQuotaStatus = {
  inactive: "inactive",
  pending: "pending",
  provisioning: "provisioning",
  active: "active",
  suspended: "suspended",
  failed: "failed",
} as const;

/**
 * Why the first purchase failed; null unless status is failed. A failed change leaves the current
 * limit in force and clears pending_limit; its Checkout Session or order shows the outcome.
 * @nullable
 */
export type SnapshotQuotaFailureReason =
  | (typeof SnapshotQuotaFailureReason)[keyof typeof SnapshotQuotaFailureReason]
  | null;

export const SnapshotQuotaFailureReason = {
  checkout_expired: "checkout_expired",
  order_declined: "order_declined",
  order_canceled: "order_canceled",
  order_expired: "order_expired",
  provisioning_failed: "provisioning_failed",
} as const;

/**
 * Snapshot count capacity for the authenticated project and one region, projected from its
 * effective quota purchase and Compute's actual holdings. This is not a Billing Allowance:
 * creation occupies capacity and confirmed deletion releases it rather than consuming a grant.
 * Pending purchases never increase effective capacity before commercial acceptance and activation.
 */
export interface SnapshotQuota {
  region_id: string;
  /**
   * inactive has no purchase; pending is a first purchase whose order has not been accepted;
   * provisioning is a first purchase being activated; active permits creation within available
   * capacity; suspended refuses new creation; failed means the first purchase failed, as
   * failure_reason states. A pending change keeps the current status and limit until it is applied.
   */
  status: SnapshotQuotaStatus;
  /**
   * Effective maximum concurrent snapshot count. Zero until the first purchase is activated.
   * @minimum 0
   */
  limit: number;
  /**
   * Held and reserved snapshot slots, including pending creation and unconfirmed cleanup.
   * @minimum 0
   */
  used: number;
  /**
   * max(limit - used, 0), or zero while creation is not permitted.
   * @minimum 0
   */
  available: number;
  /**
   * The order establishing the currently associated quota purchase, including an initial pending purchase once its checkout completes.
   * @nullable
   */
  order_id: string | null;
  /**
   * The quota purchase's Billing subscription, not an individual snapshot subscription.
   * May still be pending on an initial purchase; an existing subscription remains associated
   * until a replacement quota is activated. Null when no purchase has been recorded.
   * @nullable
   */
  subscription_id: string | null;
  /** The billing choice of the associated quota purchase, as given when it was bought. A change of an existing purchase has to give the same choice. Null when no purchase has been recorded. */
  billing: BillingChoice | null;
  /** The subscription a cancellation through Billing has to cover to release this snapshot quota. A subscription that has ended is not listed, and the list is empty when no subscription pays for the quota. */
  release_subscription_ids: string[];
  /**
   * Target count awaiting checkout or activation; null when no purchase is pending.
   * @minimum 1
   * @nullable
   */
  pending_limit: number | null;
  /**
   * Checkout Session of the pending initial purchase or change; null when none is pending.
   * @nullable
   */
  pending_checkout_session_id: string | null;
  /**
   * Order for the pending initial purchase or change once its checkout completes; null otherwise.
   * @nullable
   */
  pending_order_id: string | null;
  /**
   * Why the first purchase failed; null unless status is failed. A failed change leaves the current
   * limit in force and clears pending_limit; its Checkout Session or order shows the outcome.
   * @nullable
   */
  failure_reason: SnapshotQuotaFailureReason;
}

export interface SetSnapshotQuotaRequestBody {
  /**
   * Desired total concurrent snapshot count for this project and region, not additional slots.
   * @minimum 1
   */
  limit: number;
  billing: BillingChoice;
  checkout?: CheckoutOptions;
  /** The `proration_date` of Billing's quote for this change, so that the order is priced from the same instant. Only for automatic checkout; deferred checkout is priced when the customer completes it. Defaults to the time of the request; it must be a whole second, not in the future and at most 10 minutes old, otherwise the request is refused with `BILLING_CHANGE_INVALID`. */
  proration_date?: string;
}

