/**
 * `inactive` has never been activated or its subscription has ended; `pending` awaits acceptance of its order; `provisioning` is being activated; `active` accepts new backups; `suspended` refuses new backups and keeps existing ones; `failed` means the activation failed, as `failure_reason` states.
 */
export type BackupServiceStatus = (typeof BackupServiceStatus)[keyof typeof BackupServiceStatus];

export const BackupServiceStatus = {
  inactive: "inactive",
  pending: "pending",
  provisioning: "provisioning",
  active: "active",
  suspended: "suspended",
  failed: "failed",
} as const;

/**
 * Why the purchase failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired. `provisioning_failed` means it failed after the order was accepted, and its charge is refunded.
 * @nullable
 */
export type BackupServiceFailureReason =
  | (typeof BackupServiceFailureReason)[keyof typeof BackupServiceFailureReason]
  | null;

export const BackupServiceFailureReason = {
  checkout_expired: "checkout_expired",
  order_declined: "order_declined",
  order_canceled: "order_canceled",
  order_expired: "order_expired",
  provisioning_failed: "provisioning_failed",
} as const;

/**
 * The backup service of a project in one region. Retained backup capacity beyond what active capacity packs cover is metered on it.
 */
export interface BackupService {
  region_id: string;
  /** `inactive` has never been activated or its subscription has ended; `pending` awaits acceptance of its order; `provisioning` is being activated; `active` accepts new backups; `suspended` refuses new backups and keeps existing ones; `failed` means the activation failed, as `failure_reason` states. */
  status: BackupServiceStatus;
  /**
   * Why the purchase failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired. `provisioning_failed` means it failed after the order was accepted, and its charge is refunded.
   * @nullable
   */
  failure_reason: BackupServiceFailureReason;
  /**
   * The Checkout Session of the activation; null before an activation is requested.
   * @nullable
   */
  checkout_session_id: string | null;
  /**
   * The order that activated the service; null until the activation's checkout completes.
   * @nullable
   */
  order_id: string | null;
  /**
   * The Billing subscription that backup usage is billed under; null until the activation's checkout completes.
   * @nullable
   */
  subscription_id: string | null;
  /** The subscription a cancellation through Billing has to cover to release this backup service. A subscription that has ended is not listed, and the list is empty when no subscription pays for the service. */
  release_subscription_ids: string[];
  /**
   * The total `capacity_gib` of the backups retained in this region.
   * @minimum 0
   */
  retained_capacity_gib: number;
  /**
   * The total `capacity_gib` of the active capacity packs in this region; this much retained capacity is covered each hour.
   * @minimum 0
   */
  pack_capacity_gib: number;
}

export interface CreateBackupServiceRequestBody {
  checkout?: CheckoutOptions;
}

export interface CreateBackupServiceResponseBody {
  backup_service: BackupService;
  /** The Billing Checkout Session of this purchase. With deferred checkout, the customer completes it in Billing. */
  checkout_session_id: string;
  /**
   * The order created when checkout completes, at once for automatic checkout; null until then.
   * @nullable
   */
  order_id: string | null;
}

/**
 * `pending` awaits acceptance of its order; `provisioning` is being applied; `active` covers backup capacity; `ended` no longer does because its subscription has ended; `failed` means the purchase failed, as `failure_reason` states.
 */
export type BackupCapacityPackStatus =
  (typeof BackupCapacityPackStatus)[keyof typeof BackupCapacityPackStatus];

export const BackupCapacityPackStatus = {
  pending: "pending",
  provisioning: "provisioning",
  active: "active",
  ended: "ended",
  failed: "failed",
} as const;

/**
 * Why the purchase failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired. `provisioning_failed` means it failed after the order was accepted, and its charge is refunded.
 * @nullable
 */
export type BackupCapacityPackFailureReason =
  | (typeof BackupCapacityPackFailureReason)[keyof typeof BackupCapacityPackFailureReason]
  | null;

export const BackupCapacityPackFailureReason = {
  checkout_expired: "checkout_expired",
  order_declined: "order_declined",
  order_canceled: "order_canceled",
  order_expired: "order_expired",
  provisioning_failed: "provisioning_failed",
} as const;

/**
 * Backup capacity for one region, sold by Compute and bought for a term through its own Billing subscription. Compute applies its coverage to backup usage; it is not a Billing allowance or credit.
 */
export interface BackupCapacityPack {
  id: string;
  region_id: string;
  /** @minimum 1 */
  capacity_gib: number;
  /** `pending` awaits acceptance of its order; `provisioning` is being applied; `active` covers backup capacity; `ended` no longer does because its subscription has ended; `failed` means the purchase failed, as `failure_reason` states. */
  status: BackupCapacityPackStatus;
  /**
   * Why the purchase failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired. `provisioning_failed` means it failed after the order was accepted, and its charge is refunded.
   * @nullable
   */
  failure_reason: BackupCapacityPackFailureReason;
  /**
   * The Billing Checkout Session that bought the pack. Null when the pack was not bought through one.
   * @nullable
   */
  checkout_session_id: string | null;
  /**
   * Null until the pack's checkout completes.
   * @nullable
   */
  order_id: string | null;
  /**
   * The pack's Billing subscription, through which it is renewed or canceled.
   * @nullable
   */
  subscription_id: string | null;
  /** The subscription a cancellation through Billing has to cover to release this capacity pack. A subscription that has ended is not listed, and the list is empty when no subscription pays for the pack. */
  release_subscription_ids: string[];
  created_at: string;
}

