/**
 * Pagination metadata for keyset traversal. Pass next_cursor as cursor to read the following page; null means there is no following page.
 */
export interface CursorPagination {
  /** @minimum 1 */
  page_size: number;
  /** @nullable */
  next_cursor?: string | null;
}

/**
 * The request conflicts with the current state of a resource or offering it involves. `COMPUTE_RESOURCE_BUSY`
 * means a resource has an operation in progress: `meta.resource_type`, such as `instance` or `floating_ip`, and
 * `meta.resource_id` name it, and `meta.operation` is the type of that operation, as in its `operation` field.
 * Retry once it has finished. Other codes, such as `BILLING_OPTION_UNAVAILABLE`, are described where they
 * apply.
 */
export type ConflictResponse = Error;

export type CancellationModeParameter = CancellationMode;

